      '.gdm-boot[data-stage="4"] .gdm-holo .cap{opacity:0;}',
      '@keyframes gdm-holoBreath{0%,100%{transform:translateY(0) scale(1);filter:brightness(.92) saturate(1)}50%{transform:translateY(-5px) scale(1.015);filter:brightness(1.1) saturate(1.12)}}',
