      '.gdm-beam::before{background:linear-gradient(90deg,rgba(0,0,0,0),rgba(255,138,42,.6) 8%,rgba(120,210,255,.85) 50%,rgba(255,138,42,.6) 92%,rgba(0,0,0,0));}',
      '.gdm-pillar .rail{background:linear-gradient(90deg,#0F2E4C 0%,#071B2E 58%,#040E1A 100%);}',
      '.gdm-sight .txt{color:rgba(180,230,255,.95);}',
      '.gdm-mini{border-color:rgba(96,196,255,.3);background:linear-gradient(180deg,rgba(10,40,70,.85),rgba(4,14,26,.92));}',
      '.gdm-switchbank .sw i{border-color:rgba(96,196,255,.35);}',
      '/* 模块坞：未来小组件的入口位 */',
      '.gdm-dock{position:absolute;left:300px;bottom:10px;display:flex;gap:6px;z-index:12;pointer-events:none;}',
      '.gdm-dock .sl{width:42px;height:24px;display:grid;place-items:center;font-size:6px;letter-spacing:.12em;color:rgba(160,215,245,.7);border:1px solid rgba(96,196,255,.3);background:linear-gradient(180deg,rgba(10,40,70,.75),rgba(4,14,26,.9));font-style:normal;}',
      '.gdm-dock .sl.on{color:#8FE9FF;border-color:rgba(96,196,255,.75);box-shadow:0 0 10px rgba(80,200,255,.3);}',
      '.gdm-dock .sl.add{color:rgba(255,178,64,.85);border-color:rgba(255,138,42,.5);}',
      '/* 控制台按钮 + 抽屉 */',
      '.gdm-console-toggle{position:absolute;right:168px;bottom:12px;z-index:12;display:flex;align-items:center;gap:7px;height:26px;padding:0 14px;border:1px solid rgba(96,196,255,.55);background:linear-gradient(180deg,rgba(20,70,120,.95),rgba(6,24,44,.95));color:#DCF4FF;font-family:inherit;font-size:9px;letter-spacing:.22em;cursor:pointer;pointer-events:auto;box-shadow:0 0 14px rgba(47,168,255,.25);}',
      '.gdm-console-toggle .ic{color:#8FE9FF;}',
