      '.gdm-console-toggle.on .ic{color:#04121F;}',
      '.gdm-drawer-bg{position:fixed;inset:0;z-index:38;background:rgba(2,8,14,.42);}',
      '.gdm-drawer{position:fixed;right:0;bottom:112px;width:268px;z-index:40;transform:translateX(105%);transition:transform .32s cubic-bezier(.2,.9,.25,1);background:linear-gradient(180deg,rgba(12,48,82,.98),rgba(5,20,36,.99));border:1px solid rgba(96,196,255,.5);border-right:0;box-shadow:-14px 0 46px rgba(0,0,0,.65);pointer-events:auto;padding-bottom:8px;}',
      '.gdm-drawer.open{transform:none;}',
      '.gdm-drawer .hd{display:flex;align-items:center;gap:8px;padding:10px 12px;background:linear-gradient(90deg,#2FA8FF,#1B6FD0);color:#04121F;font-size:9px;letter-spacing:.26em;font-weight:600;}',
      '.gdm-drawer .hd i{font-style:normal;font-size:10px;}',
