      '.gdm-drawer .it{display:flex;align-items:center;gap:10px;width:100%;padding:10px 12px;background:none;border:0;border-bottom:1px solid rgba(96,196,255,.14);color:rgba(205,238,255,.92);font-family:inherit;font-size:9px;letter-spacing:.2em;cursor:pointer;text-align:left;}',
      '.gdm-drawer .it:hover{background:rgba(47,168,255,.16);}',
      '.gdm-drawer .it i{width:20px;height:20px;display:grid;place-items:center;border:1px solid rgba(96,196,255,.5);font-style:normal;font-size:9px;color:#8FE9FF;}',
      '.gdm-drawer .it em{margin-left:auto;font-style:normal;font-size:7px;letter-spacing:.18em;color:#6BE0A8;}',
      '.gdm-drawer .it.off em{color:rgba(255,138,42,.95);}',
      '.gdm-drawer .ft{display:flex;justify-content:space-between;padding:9px 12px 2px;font-size:6.5px;letter-spacing:.2em;color:rgba(150,210,240,.5);}',
      '.gdm-drawer .ft b{font-weight:400;color:rgba(255,178,64,.7);}',
