      '.gdm-vol{padding:11px 12px 5px;border-bottom:1px solid rgba(96,196,255,.14);}',
      '.gdm-vol .row{display:flex;align-items:center;gap:10px;margin-bottom:9px;font-size:7.5px;letter-spacing:.2em;color:rgba(165,220,250,.78);}',
      '.gdm-vol .row span{width:42px;}',
      '.gdm-vol .row b{width:24px;text-align:right;font-weight:400;color:#8FE9FF;}',
      '.gdm-vol input[type=range]{flex:1;-webkit-appearance:none;appearance:none;height:3px;background:rgba(96,196,255,.25);outline:none;cursor:pointer;}',
      '.gdm-vol input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:11px;height:15px;border:0;background:linear-gradient(180deg,#BFF4FF,#2FA8FF);box-shadow:0 0 10px rgba(80,200,255,.7);}',
      '.gdm-vol input[type=range]::-moz-range-thumb{width:11px;height:15px;border:0;background:#8FE9FF;}',
      '/* v16 语音语言切换 */',
