        h('path', { d: arcPath(c, c, 240, 118, 152), fill: 'none', stroke: 'rgba(' + CYAN + ',.30)', strokeWidth: 2 }),
        h('path', { d: arcPath(c, c, 240, 208, 242), fill: 'none', stroke: 'rgba(' + CYAN + ',.30)', strokeWidth: 2 })
